__NUXT_JSONP__("/por/price", (function(a,b,c,d,e,f,g,h,i,j,k,l){return {data:[{details:{slug:c,pageTitle:"Preços | Mentor Language Institute",pageDescription:"Se você já tem onde se hospedar então você não precisa pagar a ②taxa de acomodação.",title:"Preços",image:"\u002Fimages\u002Fprices\u002Fprice\u002Fget-a-quote.jpg",button:{lists:[{link:["\u003Ca class=\"btn btn-primary\" href=\"\u002Fpor\u002Fprice-auto\"\u003ECalculadora de preços\u003C\u002Fa\u003E"]}]},steps:{title:"①Mensalidade + ②Taxa de acomodação + ③Outras taxas",subtitle:["Se você já tem onde se hospedar então você não precisa pagar a ②taxa de acomodação.\u003Cbr\u003E *Por favor, use  \u003Ca href=\"\u002Fpor\u002Fprice-auto\u002F\"\u003Ea calculadora de preço\u003C\u002Fa\u003E para obter uma cotação."],lists:[{title:"①Mensalidade",subtitle:["O preço vai mudar dependendo do seu curso e da duração da sua estadia.\u003Cbr \u002F\u003E Quanto mais você estudar na MLI, maior será o desconto."],image:"\u002Fimages\u002Fprices\u002Fprice\u002FPRICE_CHART_WEB_JAN06.jpg",link:["\u003Cb\u003EP&R\u003C\u002Fb\u003E","\u003Cb\u003EP1: Posso pagar as taxas com cartão de crédito? \u003C\u002Fb\u003E\u003Cbr \u002F\u003E\u003Cb\u003ER1:\u003C\u002Fb\u003E Sim, você pode pagar com cartão de crédito. No entanto, será acrescentada uma taxa de serviço de 4%.","\u003Cb\u003EP2: Quais métodos de pagamento posso usar para pagar a MLI?\u003C\u002Fb\u003E \u003Cbr \u002F\u003E\u003Cb\u003ER2:\u003C\u002Fb\u003E Aceitamos os seguintes métodos de pagamento: \u003Cbr\u003E • Transferência bancária \u003Cbr\u003E • Transferência internacional \u003Cbr\u003E • Dinheiro \u003Cbr\u003E • Cheque pessoal \u003Cbr\u003E • Cartão de crédito \u003Cbr\u003E • Cartão de débito \u003Cbr\u003E • Zelle","Se você deseja evitar a taxa de serviço de 4% para pagamentos com cartão de crédito\u002Fdébito, pode escolher uma destas alternativas: \u003Cbr\u003E\u003Cb\u003ETransferência bancária, transferência internacional (taxa bancária de US$ 35), pagamento em dinheiro, cheque pessoal ou Zelle.\u003C\u002Fb\u003E","\u003Cb\u003EP3: Posso pagar a mensalidade depois de iniciar o programa? \u003C\u002Fb\u003E\u003Cbr \u002F\u003E\u003Cb\u003ER3:\u003C\u002Fb\u003E Não. O pagamento total deve ser feito antes ou no primeiro dia do programa."],category:[{title:"Opção de serviço",table:{tableMaxCol:d,title_optional:"Mudança de status (se você tiver o visto B1\u002FB2 e estiver atualmente nos EUA) ou ou reintegração de Status (caso o seu visto seja F1 ou J1)",tbody:[["\u003Cb\u003EDescrições de taxas\u003C\u002Fb\u003E","\u003Cb\u003ETipo de Aplicantes\u003C\u002Fb\u003E","\u003Cb\u003ETaxas\u003C\u002Fb\u003E","\u003Cb\u003ENúmero de aplicantes\u003C\u002Fb\u003E"],["Taxa de serviço de US$ 1.885, incluindo taxa de preenchimento (US$ 370) e taxa de correspondência \u003Cbr\u003E *Após a aprovação, US$ 600 serão aplicados como crédito de mensalidade para o aluno (valor não monetário).","visto de estudante F1","1,885$","1"],["Taxa de serviço de $ 365 para cada dependente","Visto de dependente F2","365$",b]]}}]},{title:"②Taxa de Acomodação",subtitle:["Nós fornecemos opções de homestay e dormitórios para estudantes. Homestay é recomendado para pessoas que gostariam de experimentar a cultura americana. Dormitórios são recomendados para pessoas que gostariam de fazer muitos amigos."],category:[{title:"Preços de homestay",table:{tableMaxCol:3,title:"Placement Fee* : $300\u003Cbr \u002F\u003E Se menor de 18 anos, o aluguel será aproximadamente 10% a mais do que o preço para uma pessoa com mais de 18 anos.",thead:[b,e,"Shared***"],tbody:[[f,a,a],[g,"$436","$384"],[h,"$872","$768"],[i,"$1,308","$1,152"],[j,"$1,744","$1,536"],[k,"$3,160","$2,904"],[l,"$4,740","$4,356"]]}},{title:"Preços de dormitórios",table:{tableMaxCol:d,title:"Placement Fee* : $200\u003Cbr \u002F\u003E Se menor de 18 anos, o aluguel será aproximadamente 10% a mais do que o preço para uma pessoa com mais de 18 anos.",thead:[b,e,"Shared (2 people)","Quad (4 people)"],tbody:[[f,a,a,a],[g,"$570","$430","$315"],[h,"$1,140","$860","$630"],[i,"$1,710","$1,290","$945"],[j,"$2,280","$1,720","$1,260"],[k,"$4,320","$3,080","$2,320"],[l,"$6,480","$4,620","$3,480"]]},description:["*Placement fee é um pagamento único. Não é reembolsável.\u003Cbr \u002F\u003E**Security deposit será reembolsado depois que os estudantes deixar a acomodação.\u003Cbr \u002F\u003E***Se você solicitar um quarto compartilhado no homestay,  \u003Cspan class=\"rmarker\"\u003Evocê deve se inscrever com outra pessoa.\u003C\u002Fspan\u003E","※A sua acomodação será fornecida pela U.S. Support Service Inc. ou outros agentes.","\u003Ca href=\"\u002Fpor\u002Fstay\u002F\"\u003E\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E  Mais informações sobre acomodações\u003C\u002Fa\u003E"]}]},{title:"③Taxas iniciais",subtitle:["Além das taxas acima, existem outras taxas iniciais."],lists:["Taxa inicial de processamento: $150","I-20 Taxa de correspondência **; $120","Taxa SEVIS **: $ 350 (pago diretamente para SEVP)","Material Didático: $150-240"],description:["*Não reembolsável\u003Cbr \u002F\u003E**Se o visto de estudante for aplicado"]}]},examples:{title:"Exemplos",subtitle:["Aqui estão exemplos de pagamentos: 4 semanas e 48 semanas"],lists:[{title:"1 mês (4 semanas)",items:["Taxa Inicial: $150","Matrícula: $1,220","Habitação: $1,630（Dormitory : Quad Rent + Placement Fee + Airport Pickup- oneway)","\u003Cspan style=\"color: #ff0000; font-weight: bold; \"\u003ETotal : $3,000\u003C\u002Fspan\u003E"]},{title:"1 ano (48 semanas)",items:["Taxa inicial: $150","Tuition : $10,032","Habitação: $13,810（Dormitory : Quad Rent + Placement Fee + Airport Pickup- oneway)","\u003Cspan style=\"color: #ff0000; font-weight: bold; \"\u003ETotal : $23,992\u003C\u002Fspan\u003E"]}]},other_info:["Você pode calcular o preço de seus estudos de inglês respondendo as perguntas abaixo."],dir:"\u002Fprice",path:"\u002Fprice\u002Fpor",extension:".json",createdAt:"2026-10-22T16:31:30.175Z",updatedAt:"2026-03-24T13:34:16.713Z"},lang:c}],fetch:{},mutations:void 0}}("$300","","por",4,"Private (Individual)","\u003Cb\u003EDeposit\u003C\u002Fb\u003E","1 week","2 weeks","3 weeks","4 weeks","8 weeks","12 weeks")));